import sys
import json
from collections import deque

def is_passable(map_id, x, y):
    # Map 0_232 is B1F
    if map_id == '0_232':
        # Southern Corridor
        if 2 <= x <= 37 and 30 <= y <= 33:
            return True
        # Chamber 1 / Eastern main area
        if 28 <= x <= 37 and 21 <= y <= 29:
            return True
        # Sofia's bypass
        if (x, y) in [(26, 31), (27, 31)]:
            return True
        # Upper bypass corridor
        if 20 <= x <= 29 and 18 <= y <= 19:
            return True
        # Western vertical/horizontal bypass corridor
        if 20 <= x <= 25 and 21 <= y <= 25:
            return True
        # Column 17 lower corridor
        if x == 17 and 27 <= y <= 31:
            return True
        # Western vertical corridor and adjacent areas
        if 14 <= x <= 17 and 5 <= y <= 21:
            return True
        # Isolated northern branch (dead end)
        if 14 <= x <= 23 and 2 <= y <= 5:
            return True
        # Ladder C corridor
        if 17 <= x <= 23 and 10 <= y <= 13:
            return True
        # Western Connecting Passage
        if 14 <= x <= 20 and 24 <= y <= 29:
            if y == 28 and (x == 14 or x >= 18):
                return False
            if y == 29 and x >= 18:
                return False
            return True
        return False

    # Map 0_82 is 1F
    elif map_id == '0_82':
        # Entrance warp tile
        if x == 15 and y == 3:
            return True
        # Starting Chamber (Chamber 1)
        if 14 <= x <= 28 and 4 <= y <= 7:
            return True
        # Eastern Corridor
        if 20 <= x <= 33 and 10 <= y <= 13:
            return True
        # East corner leading to Ladder A
        if 34 <= x <= 37 and 8 <= y <= 13:
            return True
        # Ladder A
        if x == 37 and y == 3:
            return True
        # Western system
        if 4 <= x <= 7 and 4 <= y <= 15:
            return True
        if 2 <= x <= 10 and y == 6:
            return True
        if 4 <= x <= 21 and 16 <= y <= 21:
            # Hiker sprite is blocking (5, 16)
            if x == 5 and y == 16:
                return False
            return True
        # Ladder B
        if x == 5 and y == 3:
            return True
        # Ladder C
        if x == 17 and y == 11:
            return True
        return False

    return False

def solve():
    # Read inputs
    try:
        data = json.loads(sys.argv[1])
    except Exception:
        data = {}

    start_x = int(data.get('start_x', 0))
    start_y = int(data.get('start_y', 0))
    target_x = int(data.get('target_x', 0))
    target_y = int(data.get('target_y', 0))
    map_id = data.get('map_id', '')

    if start_x == target_x and start_y == target_y:
        print(json.dumps([]))
        return

    # BFS
    queue = deque([(start_x, start_y, [])])
    visited = {(start_x, start_y)}

    while queue:
        cx, cy, path = queue.popleft()

        if cx == target_x and cy == target_y:
            print(json.dumps(path))
            return

        # Neighbors
        for nx, ny, btn in [(cx, cy - 1, 'Up'), (cx, cy + 1, 'Down'), (cx - 1, cy, 'Left'), (cx + 1, cy, 'Right')]:
            if (nx, ny) not in visited and is_passable(map_id, nx, ny):
                visited.add((nx, ny))
                queue.append((nx, ny, path + [btn]))

    print(json.dumps([]))

solve()
